/*****************************************************************************/

static void KheDrsSignatureAddAsstToShiftIndex(KHE_DRS_SIGNATURE sig, int val)
{
  HnAssert(sig->asst_to_shift_index == -1,
    "KheDrsSignatureAddAsstToShiftIndex internal error 2");
  sig->asst_to_shift_index = val;
}


