/*  bool KheDrsExprSumIntReportsCost(KHE_DRS_EXPR_SUM_INT esi)               */
/*                                                                           */
/*  Return true if esi reports a cost.                                       */
/*                                                                           */
/*****************************************************************************/

static bool KheDrsExprSumIntReportsCost(KHE_DRS_EXPR_SUM_INT esi)
{
  return esi->combined_weight > 0;
}


