/*    KHE_DRS_SOLN_SET_PART_DOM_INDEXED_TABULATED sspiu,                     */
/*    KHE_DYNAMIC_RESOURCE_SOLVER drs)                                       */
/*                                                                           */
/*  Free sspiu, but not the solutions it contains.                           */
/*                                                                           */
/*****************************************************************************/

static void KheDrsSolnSetPartDomIndexedTabulatedFree(
  KHE_DRS_SOLN_SET_PART_DOM_INDEXED_TABULATED sspiu,
  KHE_DYNAMIC_RESOURCE_SOLVER drs)
{
  KheDrsHardIndexedSolnSetFree(sspiu->indexed_solns, drs);
  HaArrayAddLast(drs->soln_set_part_dom_indexed_tabulated_free_list, sspiu);
}


