/*****************************************************************************/
/*                                                                           */
/*  void KheDrsSolnSetPartMeldSoln(KHE_DRS_SOLN_SET_PART ssp,                */
/*    KHE_DRS_SOLN soln, KHE_DRS_DAY soln_day, KHE_DRS_EXPANDER de,          */
/*    KHE_DYNAMIC_RESOURCE_SOLVER drs)                                       */
/*                                                                           */
/*  Add soln to ssp, carrying out whatever dominance testing is wanted.      */
/*                                                                           */
/*  Note.  We use "MeldSoln" for operations that do dominance testing as     */
/*  part of adding, and "AddSoln" when there is no dominance testing.        */
/*                                                                           */
/*  Implementation note.  This code expresses the generic add function:      */
/*  if soln is dominated by an existing element of ssp, delete soln,         */
/*  otherwise remove all solutions dominated by soln then add soln.          */
/*  But behind the scenes, some of the concrete subtypes don't really        */
/*  follow this structure.                                                   */
/*                                                                           */
/*****************************************************************************/

static void KheDrsSolnSetPartMeldSoln(KHE_DRS_SOLN_SET_PART ssp,
  KHE_DRS_SOLN soln, KHE_DRS_DAY soln_day, KHE_DRS_EXPANDER de,
  KHE_DYNAMIC_RESOURCE_SOLVER drs)
{
  int dom_test_count;
  dom_test_count = 0;
  if( KheDrsSolnSetPartDominates(ssp, soln, soln_day, &dom_test_count, drs) )
  {
#if TESTING
    HaArrayFill(drs->dominates_freq, dom_test_count + 1, 0);
    HaArray(drs->dominates_freq, dom_test_count)++;
#endif
    /* soln is dominated by some other soln, so delete soln */
    KheDrsSolnFree(soln, drs);
  }
  else
  {
    /* remove other solns that soln dominates, and add soln to ssp */
    KheDrsSolnSetPartRemoveDominated(ssp, soln, soln_day, drs);
    KheDrsSolnSetPartAddSoln(ssp, soln, soln_day, de, drs);
  }
}


/*****************************************************************************/
/*                                                                           */
/*  void KheDrsSolnSetPartDebug(KHE_DRS_SOLN_SET_PART ssp,                   */
/*    KHE_DYNAMIC_RESOURCE_SOLVER drs, int verbosity, int indent, FILE *fp)  */
/*                                                                           */
/*  Debug print of ssp onto fp with the given verbosity and indent.          */
/*                                                                           */
/*****************************************************************************/

static void KheDrsSolnSetPartDebug(KHE_DRS_SOLN_SET_PART ssp,
  KHE_DYNAMIC_RESOURCE_SOLVER drs, int verbosity, int indent, FILE *fp)
{
  switch( ssp->dom_kind )
  {
    case KHE_DRS_DOM_LIST_NONE:

      KheDrsSolnSetPartDomNoneDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_NONE) ssp, drs, verbosity, indent, fp);
      break;

    case KHE_DRS_DOM_LIST_SEPARATE:
    case KHE_DRS_DOM_LIST_TRADEOFF:

      KheDrsSolnSetPartDomSeparateDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_SEPARATE) ssp, drs, verbosity, indent, fp);
      break;

    case KHE_DRS_DOM_LIST_TABULATED:

      KheDrsSolnSetPartDomTabulatedDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_TABULATED) ssp, drs, verbosity, indent, fp);
      break;

    case KHE_DRS_DOM_HASH_EQUALITY:

      KheDrsSolnSetPartDomWeakDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_WEAK) ssp, drs, verbosity, indent, fp);
      break;

    case KHE_DRS_DOM_HASH_MEDIUM:

      KheDrsSolnSetPartDomMediumDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_MEDIUM) ssp, drs, verbosity, indent, fp);
      break;

    /* ***
    case KHE_DRS_DOM_TRIE_SEPARATE:
    case KHE_DRS_DOM_TRIE_TRADEOFF:

      KheDrsSolnSetPartDomTrieDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_TRIE) ssp, drs, verbosity, indent, fp);
      break;
    *** */

    case KHE_DRS_DOM_INDEXED_TRADEOFF:

      KheDrsSolnSetPartDomIndexedDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_INDEXED) ssp, drs, verbosity, indent, fp);
      break;

    case KHE_DRS_DOM_INDEXED_TABULATED:

      KheDrsSolnSetPartDomIndexedTabulatedDebug(
	(KHE_DRS_SOLN_SET_PART_DOM_INDEXED_TABULATED) ssp, drs, verbosity,
	indent, fp);
      break;

    default:

      HnAbort("KheDrsSolnSetPartDebug internal error: unknown "
	"dom_kind (%d)\n", ssp->dom_kind);
      break;
  }
}


